SELECT * FROM fund_category_map
WHERE user_id = #{userId}
  AND fund_name = #{fundName}

SELECT * FROM fund_category_map
WHERE user_id = #{userId}
  AND fund_name IN

      #{name}

SELECT * FROM fund_category_map
WHERE user_id = #{userId}
  AND fund_name = #{fundName}
  AND source = 'user_correct'

SELECT * FROM fund_category_map
WHERE user_id = #{userId}
  AND source = 'user_correct'
  AND last_seen_at IS NOT NULL
  AND last_seen_at < #{cutoffDate}
ORDER BY last_seen_at ASC

mapper.update:
UPDATE fund_category_map
SET last_seen_at = CURRENT_TIMESTAMP,
    source = #{source}
WHERE user_id = #{userId}
  AND fund_name = #{fundName}

mapper.delete:
DELETE FROM fund_category_map
WHERE user_id = #{userId}
  AND fund_name = #{fundName}
